// Initialize image slider
function initImageSlider() {
  const slider = document.getElementById('autoSlider');
  if (slider) {
      // Add images to slider
      const images = [
          "https://cdn.shopify.com/s/files/1/2675/9476/files/different-type-white-aroma-tea-cups-with-herbs-wooden-table_23-2148091982_1024x1024.jpg?v=1610040290",
          "https://th.bing.com/th/id/OIP.L1Irjq373lWB71fELATMOAHaE8?w=273&h=183&c=7&r=0&o=5&dpr=1.3&pid=1.7",
          "data:image/jpeg;base64,",
          "https://th.bing.com/th/id/OIP.G5pO4LWmDySo_awEqs_LvgHaEJ?w=276&h=180&c=7&r=0&o=5&dpr=1.3&pid=1.7",
          "data:image/jpeg;base64,"
      ];
      
      // Add images twice for seamless looping
      images.concat(images).forEach(img => {
          const imgElement = document.createElement('img');
          imgElement.src = img;
          slider.appendChild(imgElement);
      });
  }
}

// Auto-scroll functionality for slider
let scrollAmount = 0;
function autoScroll() {
  const slider = document.getElementById('autoSlider');
  if (slider) {
      if (scrollAmount >= slider.scrollWidth / 2) {
          scrollAmount = 0;
      } else {
          scrollAmount += 1;
      }
      slider.scrollTo({
          left: scrollAmount,
          behavior: 'smooth'
      });
  }
}

// Display menu items
function displayMenu(items) {
  const container = document.getElementById("menu-container");
  container.innerHTML = "";

  items.forEach(item => {
      const card = document.createElement("div");
      card.className = "menu-card";

      card.innerHTML = `
          <img src="${item.image}" alt="${item.name}">
          <h3>${item.name}</h3>
          <p>₹${item.price}</p>
          <button onclick="buyItem('${item.name}', ${item.price})">Buy Now</button>
      `;

      container.appendChild(card);
  });
}

// Handle buy item
function buyItem(name, price) {
  const currentUser = JSON.parse(sessionStorage.getItem('currentUser'));

  if (confirm(`Would you like to order ${name} for ₹${price}?`)) {
      // Create order
      const order = {
          id: 'ord_' + Date.now(),
          customerName: currentUser.name,
          customerEmail: currentUser.email,
          date: new Date().toISOString(),
          items: [{ name, quantity: 1, price }],
          total: price,
          status: 'Pending'
      };

      // Save order
      let orders = JSON.parse(localStorage.getItem('orders')) || [];
      orders.push(order);
      localStorage.setItem('orders', JSON.stringify(orders));

      alert(`Your order of ${name} has been placed successfully! Thank you.`);
  } else {
      alert('Order cancelled. Let us know if you change your mind!');
  }
}

