function buyNow(itemName, price) {
    if (confirm(`Do you want to confirm your order for ${itemName} at ₹${price}?`)) {
        document.getElementById('orderedItem').value = itemName;
        document.getElementById('orderedPrice').value = price;
        document.getElementById('order-form-container').style.display = 'block';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('orderForm');
    if (form) {
        form.addEventListener('submit', function (e) {
            e.preventDefault();

            // Get form data
            const formData = new FormData(form);
            const formObject = {};
            formData.forEach((value, key) => {
                formObject[key] = value;
            });

            // Save the order data to localStorage
            let orders = JSON.parse(localStorage.getItem('orders')) || [];
            const orderId = 'ord_' + Date.now(); // Generate unique order ID

            const order = {
                id: orderId,
                ...formObject,
                status: 'Pending',
                date: new Date().toISOString(),
            };

            orders.push(order);
            localStorage.setItem('orders', JSON.stringify(orders));

            // Show confirmation
            alert('Your order has been placed successfully!');

            // Reset form and hide the order form container
            form.reset();
            document.getElementById('order-form-container').style.display = 'none';
        });
    }
});




  



// Admin credentials for login (these can be replaced with actual credentials or database authentication)
const adminCredentials = {
    email: 'admin@serenitea.com',
    password: 'admin123' // Change this to a secure password
};

// Function to handle admin login
function loginAdmin(event) {
    event.preventDefault(); // Prevent form submission

    const email = document.getElementById('adminEmail').value;
    const password = document.getElementById('adminPassword').value;

    // Check if the credentials match
    if (email === adminCredentials.email && password === adminCredentials.password) {
        // If valid, show the admin dashboard
        document.getElementById('admin-login-container').style.display = 'none';
        document.getElementById('admin-dashboard').style.display = 'block';

        // Optionally, you can store login status in localStorage or sessionStorage
        sessionStorage.setItem('isAdminLoggedIn', 'true');
        alert('Login successful!');

        // Call function to display orders (this can be customized)
        displayAllOrders();
    } else {
        // Show an error message for invalid credentials
        alert('Invalid email or password!');
    }
}

// Function to display all orders in the admin dashboard (from localStorage)
function displayAllOrders() {
    const ordersContainer = document.getElementById('admin-dashboard');
    ordersContainer.innerHTML = '<h2>Orders</h2>'; // Clear previous content

    // Get all orders from localStorage
    const orders = JSON.parse(localStorage.getItem('orders')) || [];

    if (orders.length === 0) {
        ordersContainer.innerHTML += '<p>No orders placed yet.</p>';
        return;
    }

    // Loop through orders and display them
    orders.forEach(order => {
        const orderElement = document.createElement('div');
        orderElement.className = 'order-card';
        orderElement.innerHTML = `
            <h3>Order ID: ${order.id}</h3>
            <p>Customer: ${order.customerName}</p>
            <p>Item: ${order.item}</p>
            <p>Total: ₹${order.total}</p>
            <p>Status: <span id="status-${order.id}">${order.status}</span></p>
            <button onclick="viewOrderDetails('${order.id}')">View Details</button>
            <button onclick="updateOrderStatus('${order.id}')">Update Status</button>
        `;
        ordersContainer.appendChild(orderElement);
    });
}

// Function to update order status
function updateOrderStatus(orderId) {
    const orders = JSON.parse(localStorage.getItem('orders')) || [];
    const order = orders.find(order => order.id === orderId);

    if (!order) {
        alert('Order not found!');
        return;
    }

    const newStatus = prompt("Enter the new status for this order (Pending, Shipped, Delivered):", order.status);

    if (newStatus && ['Pending', 'Shipped', 'Delivered'].includes(newStatus)) {
        order.status = newStatus;
        localStorage.setItem('orders', JSON.stringify(orders));

        document.getElementById(`status-${orderId}`).innerText = newStatus;
        alert('Order status updated successfully!');
    } else {
        alert('Invalid status!');
    }
}

// Function to view order details
function viewOrderDetails(orderId) {
    const orders = JSON.parse(localStorage.getItem('orders')) || [];
    const order = orders.find(order => order.id === orderId);

    if (!order) {
        alert('Order not found!');
        return;
    }

    const orderDetailsContainer = document.createElement('div');
    orderDetailsContainer.innerHTML = `
        <h2>Order Details</h2>
        <p><strong>Order ID:</strong> ${order.id}</p>
        <p><strong>Customer Name:</strong> ${order.customerName}</p>
        <p><strong>Email:</strong> ${order.customerEmail}</p>
        <p><strong>Contact:</strong> ${order.contact}</p>
        <p><strong>Address:</strong> ${order.address}</p>
        <p><strong>State:</strong> ${order.state}</p>
        <p><strong>Country:</strong> ${order.country}</p>
        <p><strong>Item:</strong> ${order.item}</p>
        <p><strong>Price:</strong> ₹${order.price}</p>
        <p><strong>Total:</strong> ₹${order.total}</p>
        <p><strong>Status:</strong> ${order.status}</p>
        <p><strong>Date:</strong> ${new Date(order.date).toLocaleString()}</p>
        <button onclick="closeOrderDetails()">Close</button>
    `;
    document.body.appendChild(orderDetailsContainer);
}

// Function to close the order details view
function closeOrderDetails() {
    const orderDetailsContainer = document.querySelector('div');
    document.body.removeChild(orderDetailsContainer);
}
